            index += 1
            V = int(data[index]) - 1
            index += 1
            queries.append((U, V))

        # Build the tree
        tree = defaultdict(list)
        for x, y in edges:
            tree[x].append(y)
            tree[y].append(x)

        # Find LCA using binary lifting
        MAX_LOG = 20
        parent = [[-1] * MAX_LOG for _ in range(N)]
        depth = [0] * N

        def dfs(node, par, d):
            parent[node][0] = par
            depth[node] = d
            for child in tree[node]:
                if child != par:
                    dfs(child, node, d + 1)

        dfs(0, -1, 0)

        for k in range(1, MAX_LOG):
            for node in range(N):
                if parent[node][k - 1] != -1:
                    parent[node][k] = parent[parent[node][k - 1]][k - 1]

        def lca(u, v):
            if depth[u] > depth[v]:
                u, v = v, u
            diff = depth[v] - depth[u]
            for k in range(MAX_LOG):
                if diff & (1 << k):
                    v = parent[v][k]
            if u == v:
                return u
            for k in range(MAX_LOG - 1, -1, -1):
                if parent[u][k] != parent[v][k]:
                    u = parent[u][k]
                    v = parent[v][k]
            return parent[u][0]

