            if l == U:
                path = dis[V]
            elif l == V:
                path = dis[U][::-1]
            else:
                path = dis[U][:-1][::-1] + dis[V][1:]

            # Check if there exists a palindrome subsequence
            found = False
            for i in range(len(path)):
                for j in range(i + 1, len(path)):
                    if path[i] == path[j]:
                        found = True
                        break
                if found:
                    break

            results.append("YES" if found else "NO")

    print("\n".join(results))

